import { useState, useEffect } from 'react';
import styles from './SummaryCard.module.css';

const SummaryCard = ({ 
  totalIncome: propTotalIncome, 
  totalExpenses: propTotalExpenses, 
  balance: propBalance, 
  currentBalance: propCurrentBalance 
}) => {
  // Estados con valores por defecto desde localStorage o props
  const [totalIncome, setTotalIncome] = useState(() => {
    const saved = localStorage.getItem('totalIncome');
    return saved !== null ? Number(saved) : propTotalIncome || 0;
  });

  const [totalExpenses, setTotalExpenses] = useState(() => {
    const saved = localStorage.getItem('totalExpenses');
    return saved !== null ? Number(saved) : propTotalExpenses || 0;
  });

  const [balance, setBalance] = useState(() => {
    const saved = localStorage.getItem('balance');
    return saved !== null ? Number(saved) : propBalance || 0;
  });

  const [currentBalance, setCurrentBalance] = useState(() => {
    const saved = localStorage.getItem('currentBalance');
    return saved !== null ? Number(saved) : propCurrentBalance || 0;
  });

  // Efecto para guardar en localStorage cuando los valores cambien
  useEffect(() => {
    localStorage.setItem('totalIncome', totalIncome.toString());
    localStorage.setItem('totalExpenses', totalExpenses.toString());
    localStorage.setItem('balance', balance.toString());
    localStorage.setItem('currentBalance', currentBalance.toString());
  }, [totalIncome, totalExpenses, balance, currentBalance]);

  // Función para actualizar todos los valores
  const updateFinancials = (newIncome, newExpenses, newBalance, newCurrentBalance) => {
    setTotalIncome(newIncome);
    setTotalExpenses(newExpenses);
    setBalance(newBalance);
    setCurrentBalance(newCurrentBalance);
  };

  return (
    <div className={styles.card}>
      <h3>Resumen Financiero</h3>
      <div className={styles.summaryItem}>
        <p>Ingresos: ${totalIncome}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Gastos: ${totalExpenses}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Balance: ${balance}</p>
      </div>
      <div className={styles.summaryItem}>
        <p>Saldo Actual: ${currentBalance}</p>
      </div>
      
      {/* Opcional: Botones para modificar los valores */}
      <div className={styles.controls}>
        <button onClick={() => updateFinancials(
          totalIncome + 100,
          totalExpenses,
          balance + 100,
          currentBalance + 100
        )}>
          Añadir Ingreso
        </button>
        
        <button onClick={() => updateFinancials(
          totalIncome,
          totalExpenses + 50,
          balance - 50,
          currentBalance - 50
        )}>
          Añadir Gasto
        </button>
      </div>
    </div>
  );
};

export default SummaryCard;
